<div style="margin-top:6px;color:#555;font-style:italic;">Drag the purple dots P₁ and P₂ to move them — Δr always closes the triangle.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Element spec ─────────────────────────────────────────────────────────────
// x-axis → Line (black) + ConeGeometry arrowhead at +X end, label 'x'
// y-axis → Line (black) + ConeGeometry arrowhead at +Y end, label 'y'
// z-axis → Line (black) + ConeGeometry arrowhead at +Z end, label 'z'
// P1, P2 → SphereGeometry(0.12) purple #7b2d8b, draggable
// r(t1), r(t2), Δr → fat arrows: CylinderGeometry shaft (r=0.06) + ConeGeometry head, purple
// labels → addLabel floating HTML, purple italic for vectors, black italic for axes

const PURPLE = 0x7b2d8b;

// ── Axes ────────────────────────────────────────────────────────────────────
const AXIS_LEN = 3;
const axisMat = new THREE.LineBasicMaterial({ color: 0x000000 });
function makeAxis(dir) {
  const end = dir.clone().multiplyScalar(AXIS_LEN);
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), end]),
    axisMat
  );
  scene.add(line);
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(0.055, 0.2, 12),
    new THREE.MeshBasicMaterial({ color: 0x000000 })
  );
  cone.position.copy(dir.clone().multiplyScalar(AXIS_LEN + 0.1));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(cone);
}
makeAxis(new THREE.Vector3(1, 0, 0));
makeAxis(new THREE.Vector3(0, 1, 0));
makeAxis(new THREE.Vector3(0, 0, 1));
addLabel('<i>x</i>', new THREE.Vector3(3.25, -0.12, 0), { color: '#000', fontSize: '15px' });
addLabel('<i>y</i>', new THREE.Vector3(0.15, 3.25, 0), { color: '#000', fontSize: '15px' });
addLabel('<i>z</i>', new THREE.Vector3(-0.12, 0, 3.3), { color: '#000', fontSize: '15px' });

// NOTE: scaffold is Y-up, but the figure treats Z as vertical on screen. We keep
// world coords as given (x out-of-page, y right, z up) and instead roll the
// camera so world Z appears vertical — simpler: rotate the whole content group.
// Wrap all content in a group rotated -90° about X so world +Z maps to screen up.
const content = new THREE.Group();
content.rotation.x = -Math.PI / 2; // world (x,y,z) -> three (x, z, -y): z becomes up
scene.add(content);

// Rebuild axes inside content instead
scene.children.filter(o => o !== content && (o.isLine || (o.isMesh && o.geometry.type === 'ConeGeometry' && o.material.color.getHex() === 0x000000)))
  .forEach(o => scene.remove(o));
function makeAxis2(dir) {
  const end = dir.clone().multiplyScalar(AXIS_LEN);
  content.add(new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), end]),
    axisMat
  ));
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(0.055, 0.2, 12),
    new THREE.MeshBasicMaterial({ color: 0x000000 })
  );
  cone.position.copy(dir.clone().multiplyScalar(AXIS_LEN + 0.1));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  content.add(cone);
}
makeAxis2(new THREE.Vector3(1, 0, 0));
makeAxis2(new THREE.Vector3(0, 1, 0));
makeAxis2(new THREE.Vector3(0, 0, 1));

// ── Points P1, P2 (world coords in figure space: x,y,z with z up) ───────────
const p1 = new THREE.Vector3(0.4, 1.8, 1.9);
const p2 = new THREE.Vector3(1.2, 2.9, 0.6);
const dotGeom = new THREE.SphereGeometry(0.12, 20, 16);
const dotMat = new THREE.MeshBasicMaterial({ color: PURPLE });
const dot1 = new THREE.Mesh(dotGeom, dotMat);
const dot2 = new THREE.Mesh(dotGeom, dotMat.clone());
content.add(dot1, dot2);

// ── Fat arrows ──────────────────────────────────────────────────────────────
function makeFatArrow() {
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(
    new THREE.CylinderGeometry(0.06, 0.06, 1, 14),
    new THREE.MeshBasicMaterial({ color: PURPLE })
  );
  const head = new THREE.Mesh(
    new THREE.ConeGeometry(0.14, 0.4, 16),
    new THREE.MeshBasicMaterial({ color: PURPLE })
  );
  g.add(shaft, head);
  g.userData = { shaft, head };
  content.add(g);
  return g;
}
const arrR1 = makeFatArrow();
const arrR2 = makeFatArrow();
const arrDR = makeFatArrow();

const _up = new THREE.Vector3(0, 1, 0);
const _dir = new THREE.Vector3();
function setArrow(g, a, b) {
  _dir.subVectors(b, a);
  const len = _dir.length();
  if (len < 1e-6) { g.visible = false; return; }
  _dir.normalize();
  g.quaternion.setFromUnitVectors(_up, _dir);
  const headLen = Math.min(0.4, len * 0.35);
  const shaftLen = Math.max(0.01, len - headLen);
  g.userData.shaft.scale.set(1, shaftLen, 1);
  g.userData.shaft.position.set(0, shaftLen / 2, 0);
  g.userData.head.scale.set(1, headLen / 0.4, 1);
  g.userData.head.position.set(0, shaftLen + headLen / 2, 0);
  g.position.copy(a);
}

// ── Labels ──────────────────────────────────────────────────────────────────
const PURPLE_CSS = '#7b2d8b';
const lblP1 = addLabel('<i>P</i><sub>1</sub>', new THREE.Vector3(), { color: PURPLE_CSS, fontSize: '16px', offset: [16, -12] });
const lblP2 = addLabel('<i>P</i><sub>2</sub>', new THREE.Vector3(), { color: PURPLE_CSS, fontSize: '16px', offset: [18, 8] });
const lblR1 = addLabel('<b>r&#8407;</b>(<i>t</i><sub>1</sub>)', new THREE.Vector3(), { color: PURPLE_CSS, fontSize: '16px', offset: [-24, 6] });
const lblR2 = addLabel('<b>r&#8407;</b>(<i>t</i><sub>2</sub>)', new THREE.Vector3(), { color: PURPLE_CSS, fontSize: '16px', offset: [-24, 10] });
const lblDR = addLabel('&Delta;<b>r&#8407;</b>', new THREE.Vector3(), { color: PURPLE_CSS, fontSize: '16px', offset: [26, 0] });

// ── Rebuild everything from live endpoints ──────────────────────────────────
const _w = new THREE.Vector3();
function figureToWorld(v) { return _w.copy(v).applyMatrix4(content.matrixWorld); }
function updateFigure() {
  dot1.position.copy(p1);
  dot2.position.copy(p2);
  setArrow(arrR1, new THREE.Vector3(0, 0, 0), p1);
  setArrow(arrR2, new THREE.Vector3(0, 0, 0), p2);
  setArrow(arrDR, p1, p2);
  content.updateMatrixWorld();
  lblP1.pos.copy(figureToWorld(p1));
  lblP2.pos.copy(figureToWorld(p2));
  lblR1.pos.copy(figureToWorld(p1.clone().multiplyScalar(0.55)));
  lblR2.pos.copy(figureToWorld(p2.clone().multiplyScalar(0.5)));
  lblDR.pos.copy(figureToWorld(p1.clone().add(p2).multiplyScalar(0.5)));
}
updateFigure();

// ── Visibility sequence control ─────────────────────────────────────────────
const SEQ_STATES = ['idle', 'r1', 'r2', 'deltaR'];
let seqState = 'idle';
function applySeqState(s) {
  seqState = s;
  arrR1.visible = s !== 'idle';
  lblR1.div.style.visibility = s !== 'idle' ? '' : 'hidden';
  arrR2.visible = s === 'r2' || s === 'deltaR';
  lblR2.div.style.visibility = arrR2.visible ? '' : 'hidden';
  arrDR.visible = s === 'deltaR';
  lblDR.div.style.visibility = arrDR.visible ? '' : 'hidden';
  const hint = document.getElementById('seqHint');
  if (hint) hint.textContent = {
    idle: 'Click to reveal vectors in order',
    r1: 'r⃗(t₁): position at time t₁',
    r2: 'r⃗(t₂): position at time t₂',
    deltaR: 'Δr⃗ = r⃗(t₂) − r⃗(t₁)'
  }[s];
}
document.getElementById('btnSeq').addEventListener('click', () => {
  const next = SEQ_STATES[(SEQ_STATES.indexOf(seqState) + 1) % SEQ_STATES.length];
  applySeqState(next);
  document.getElementById('stepNarration').textContent = '';
});
applySeqState('idle');

// ── Demo steps ──────────────────────────────────────────────────────────────
const DEMO = [
  { narration: "Only r(t₁) is drawn, from the origin to P₁: the particle's position at time t₁.", state: 'r1' },
  { narration: 'r(t₂) appears, reaching the later position P₂. The two position vectors share the origin as their tail.', state: 'r2' },
  { narration: 'Δr appears as the arrow from P₁ to P₂. The triangle relation r(t₁) + Δr = r(t₂) is now visible: Δr = r(t₂) − r(t₁).', state: 'deltaR' },
];
function goToStep(i) {
