  document.getElementById('stepNarration').textContent = step.narration;
  document.querySelectorAll('.stepBtn').forEach((b, j) =>
    b.classList.toggle('active', j === i));
}
document.querySelectorAll('.stepBtn').forEach((b, i) =>
  b.addEventListener('click', () => goToStep(i)));

// ── Drag endpoints (raycast onto camera-parallel plane through the point) ───
const dragRay = new THREE.Raycaster();
const dragPtr = new THREE.Vector2();
const dragPlane = new THREE.Plane();
let dragging = null; // { which: 1|2 }

function setDragPointer(e) {
  const rect = canvas.getBoundingClientRect();
  dragPtr.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  dragPtr.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
}

canvas.addEventListener('pointerdown', (e) => {
  setDragPointer(e);
  dragRay.setFromCamera(dragPtr, camera);
  content.updateMatrixWorld();
  const hits = dragRay.intersectObjects([dot1, dot2], false);
  if (!hits.length) return;
  dragging = { which: hits[0].object === dot1 ? 1 : 2 };
  controls.enabled = false;
  // Plane through the point, perpendicular to the view direction (parallel to screen)
  const worldPt = hits[0].object.getWorldPosition(new THREE.Vector3());
  const camDir = new THREE.Vector3();
  camera.getWorldDirection(camDir);
  dragPlane.setFromNormalAndCoplanarPoint(camDir, worldPt);
  canvas.setPointerCapture(e.pointerId);
  e.stopPropagation();
}, true);

canvas.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  setDragPointer(e);
  dragRay.setFromCamera(dragPtr, camera);
  const worldPt = new THREE.Vector3();
  if (!dragRay.ray.intersectPlane(dragPlane, worldPt)) return;
  // Convert world hit back into content (figure) coordinates
  const local = content.worldToLocal(worldPt.clone());
  local.x = Math.max(-2.8, Math.min(2.8, local.x));
  local.y = Math.max(-2.8, Math.min(2.8, local.y));
  local.z = Math.max(-2.8, Math.min(2.8, local.z));
  if (dragging.which === 1) p1.copy(local); else p2.copy(local);
  updateFigure();
});

window.addEventListener('pointerup', () => {
  if (dragging) { dragging = null; controls.enabled = true; }
});

// Hover affordance on the dots
canvas.addEventListener('pointermove', (e) => {
  if (dragging) { canvas.style.cursor = 'grabbing'; return; }
  setDragPointer(e);
  dragRay.setFromCamera(dragPtr, camera);
  const hits = dragRay.intersectObjects([dot1, dot2], false);
  if (hits.length) canvas.style.cursor = 'grab';
});

registerInteractive(dot1, {
  title: 'Point P₁',
  tooltip: 'P₁ — drag to move',
  body: 'Position of the particle at time t₁. The vector r⃗(t₁) points from the origin here.'
});
registerInteractive(dot2, {
  title: 'Point P₂',
  tooltip: 'P₂ — drag to move',
  body: 'Position of the particle at time t₂. The displacement Δr⃗ = r⃗(t₂) − r⃗(t₁) always runs from P₁ to P₂.'
});

// ── Camera (after all geometry) ─────────────────────────────────────────────
// Content group maps figure (x,y,z) with z-up into three.js y-up. Standard
// isometric pose: axisScreenAngles {x:30, z:30} — here those correspond to the
// figure's x (receding lower-left) and y (right) horizontal axes.
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  heightFraction: 0.65,
});

goToStep(0);
// @FIGURE_CODE_END

