userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<button id="btnSeq">Build displacement</button>
<div id="seqHint" style="font-style:italic;color:#555;">Δr⃗ = r⃗(t₂) − r⃗(t₁)</div>
<div style="margin-top:6px;font-weight:bold;">Demo steps</div>
<button class="stepBtn" data-step="0">1 · First position vector</button>
<button class="stepBtn" data-step="1">2 · Second position vector</button>
<button class="stepBtn" data-step="2">3 · Displacement closes the triangle</button>
<div id="stepNarration" style="color:#333;max-width:240px;"></div>
<div style="margin-top:6px;color:#555;font-style:italic;">Drag the purple dots P₁ and P₂ to move them — Δr⃗ always closes the triangle.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Element spec ─────────────────────────────────────────────────────────────
// Figure space: (x, y, z) with z vertical (as in the source). A content group
// rotated -90° about world X maps figure coords (x,y,z) -> three.js (x, z, -y),
// so world +Y (screen-vertical) carries the figure's z-axis. No sheared geometry.
//   x-axis → Line (black, thin) + ConeGeometry(0.05,0.18) head at +X tip, label x
//   y-axis → Line (black, thin) + ConeGeometry head at +Y tip, label y
//   z-axis → Line (black, thin) + ConeGeometry head at +Z tip, label z
//   P1, P2 → SphereGeometry(0.12) purple #7b2d8b, draggable
//   r(t1), r(t2), Δr → fat arrows: CylinderGeometry shaft (r=0.07) + ConeGeometry
//     head (r=0.16), purple — heavy weight matching the source
//   labels → addLabel, purple italic for vectors, black italic for axis tips

const PURPLE = 0x7b2d8b;
const PURPLE_CSS = '#7b2d8b';
const AXIS_LEN = 3;

// ── Content group: figure z-up -> three.js y-up ─────────────────────────────
const content = new THREE.Group();
content.rotation.x = -Math.PI / 2; // figure (x,y,z) -> world (x, z, -y)
scene.add(content);

const _w = new THREE.Vector3();
function figureToWorld(v) {
  content.updateMatrixWorld();
  return _w.copy(v).applyMatrix4(content.matrixWorld).clone();
}

// ── Axes (thin black lines with small arrowheads, built in figure space) ────
const axisMat = new THREE.LineBasicMaterial({ color: 0x000000 });
function makeAxis(dir) {
  const end = dir.clone().multiplyScalar(AXIS_LEN);
  content.add(new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), end]),
    axisMat
  ));
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(0.05, 0.18, 12),
    new THREE.MeshBasicMaterial({ color: 0x000000 })
  );
  cone.position.copy(dir.clone().multiplyScalar(AXIS_LEN + 0.09));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  content.add(cone);
}
makeAxis(new THREE.Vector3(1, 0, 0)); // figure x: recedes toward lower-left
makeAxis(new THREE.Vector3(0, 1, 0)); // figure y: extends right
makeAxis(new THREE.Vector3(0, 0, 1)); // figure z: straight up

// Axis labels pinned to their arrow tips (world-space via the rotated group)
addLabel('<i>x</i>', figureToWorld(new THREE.Vector3(3.3, -0.15, -0.1)), { color: '#000', fontSize: '15px' });
addLabel('<i>y</i>', figureToWorld(new THREE.Vector3(0.15, 3.3, 0)), { color: '#000', fontSize: '15px' });
addLabel('<i>z</i>', figureToWorld(new THREE.Vector3(-0.18, 0, 3.3)), { color: '#000', fontSize: '15px' });

// ── Points P1, P2 (figure coords, z up) ─────────────────────────────────────
// P1 above-right of origin; P2 lower and farther right.
const p1 = new THREE.Vector3(0.4, 1.8, 1.9);
const p2 = new THREE.Vector3(1.2, 2.9, 0.6);
const dotGeom = new THREE.SphereGeometry(0.12, 20, 16);
const dot1 = new THREE.Mesh(dotGeom, new THREE.MeshBasicMaterial({ color: PURPLE }));
const dot2 = new THREE.Mesh(dotGeom, new THREE.MeshBasicMaterial({ color: PURPLE }));
content.add(dot1, dot2);

// ── Fat arrows ──────────────────────────────────────────────────────────────
function makeFatArrow() {
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(
    new THREE.CylinderGeometry(0.07, 0.07, 1, 14),
    new THREE.MeshBasicMaterial({ color: PURPLE })
  );
  const head = new THREE.Mesh(
    new THREE.ConeGeometry(0.16, 0.42, 16),
    new THREE.MeshBasicMaterial({ color: PURPLE })
  );
  g.add(shaft, head);
  g.userData = { shaft, head };
  content.add(g);
  return g;
}
const arrR1 = makeFatArrow();
const arrR2 = makeFatArrow();
const arrDR = makeFatArrow();

const _up = new THREE.Vector3(0, 1, 0);
const _dir = new THREE.Vector3();
function setArrow(g, a, b) {
  _dir.subVectors(b, a);
  const len = _dir.length();
  if (len < 1e-6) { g.visible = false; return; }
  g.visible = true;
  _dir.normalize();
  g.quaternion.setFromUnitVectors(_up, _dir);
  const headLen = Math.min(0.42, len * 0.3);
  const shaftLen = Math.max(0.01, len - headLen);
  g.userData.shaft.scale.set(1, shaftLen, 1);
  g.userData.shaft.position.set(0, shaftLen / 2, 0);
  g.userData.head.scale.set(1, headLen / 0.42, 1);
  g.userData.head.position.set(0, shaftLen + headLen / 2, 0);
  g.position.copy(a);
}

// ── Vector / point labels ───────────────────────────────────────────────────
const lblP1 = addLabel('<i>P</i><sub>1</sub>', new THREE.Vector3(), { color: PURPLE_CSS, fontSize: '16px', offset: [14, -14] });
const lblP2 = addLabel('<i>P</i><sub>2</sub>', new THREE.Vector3(), { color: PURPLE_CSS, fontSize: '16px', offset: [14, 14] });
const lblR1 = addLabel('<b>r&#8407;</b>(<i>t</i><sub>1</sub>)', new THREE.Vector3(), { color: PURPLE_CSS, fontSize: '16px', offset: [-30, 14] });
const lblR2 = addLabel('<b>r&#8407;</b>(<i>t</i><sub>2</sub>)', new THREE.Vector3(), { color: PURPLE_CSS, fontSize: '16px', offset: [-34, -2] });
const lblDR = addLabel('&Delta;<b>r&#8407;</b>', new THREE.Vector3(), { color: PURPLE_CSS, fontSize: '16px', offset: [26, -6] });

// ── Rebuild all arrows/labels from the live endpoints ───────────────────────
function updateFigure() {
  dot1.position.copy(p1);
  dot2.position.copy(p2);
  setArrow(arrR1, new THREE.Vector3(0, 0, 0), p1);
  setArrow(arrR2, new THREE.Vector3(0, 0, 0), p2);
  setArrow(arrDR, p1, p2);
  content.updateMatrixWorld();
  lblP1.pos.copy(figureToWorld(p1));
  lblP2.pos.copy(figureToWorld(p2));
  lblR1.pos.copy(figureToWorld(p1.clone().multiplyScalar(0.55)));
  lblR2.pos.copy(figureToWorld(p2.clone().multiplyScalar(0.5)));
  lblDR.pos.copy(figureToWorld(p1.clone().add(p2).multiplyScalar(0.5)));
}
updateFigure();

// ── Visibility sequence control ─────────────────────────────────────────────
const SEQ_STATES = ['idle', 'r1', 'r2', 'deltaR'];
let seqState = 'deltaR';
function applySeqState(s) {
  seqState = s;
  arrR1.visible = s !== 'idle';
  lblR1.div.style.visibility = s !== 'idle' ? '' : 'hidden';
  arrR2.visible = s === 'r2' || s === 'deltaR';
  lblR2.div.style.visibility = arrR2.visible ? '' : 'hidden';
  arrDR.visible = s === 'deltaR';
  lblDR.div.style.visibility = arrDR.visible ? '' : 'hidden';
  const hint = document.getElementById('seqHint');
  if (hint) hint.textContent = {
    idle: 'Click to reveal vectors in order',
    r1: 'r⃗(t₁): position at time t₁',
    r2: 'r⃗(t₂): position at time t₂',
    deltaR: 'Δr⃗ = r⃗(t₂) − r⃗(t₁)'
  }[s];
}
document.getElementById('btnSeq').addEventListener('click', () => {
  const next = SEQ_STATES[(SEQ_STATES.indexOf(seqState) + 1) % SEQ_STATES.length];
  applySeqState(next);
  document.getElementById('stepNarration').textContent = '';
  document.querySelectorAll('.stepBtn').forEach(b => b.classList.remove('active'));
});

// ── Demo steps ──────────────────────────────────────────────────────────────
const DEMO = [
  { narration: "Only r(t₁) is drawn, from the origin to P₁: the particle's position at time t₁.", state: 'r1' },
  { narration: 'r(t₂) appears, reaching the later position P₂. The two position vectors share the origin as their tail.', state: 'r2' },
  { narration: 'Δr appears as the arrow from P₁ to P₂. The triangle relation r(t₁) + Δr = r(t₂) is now visible: Δr = r(t₂) − r(t₁).', state: 'deltaR' },
];
function goToStep(i) {
  const step = DEMO[i];
  applySeqState(step.state);
  document.getElementById('stepNarration').textContent = step.narration;
  document.querySelectorAll('.stepBtn').forEach((b, j) =>
    b.classList.toggle('active', j === i));
}
document.querySelectorAll('.stepBtn').forEach((b, i) =>
  b.addEventListener('click', () => goToStep(i)));

// ── Drag endpoints (raycast onto a camera-parallel plane through the point) ─
const dragRay = new THREE.Raycaster();
const dragPtr = new THREE.Vector2();
const dragPlane = new THREE.Plane();
let dragging = null;

function setDragPointer(e) {
  const rect = canvas.getBoundingClientRect();
  dragPtr.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  dragPtr.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
}

canvas.addEventListener('pointerdown', (e) => {
  setDragPointer(e);
  dragRay.setFromCamera(dragPtr, camera);
  content.updateMatrixWorld();
  const hits = dragRay.intersectObjects([dot1, dot2], false);
  if (!hits.length) return;
  dragging = { which: hits[0].object === dot1 ? 1 : 2 };
  controls.enabled = false;
  const worldPt = hits[0].object.getWorldPosition(new THREE.Vector3());
  const camDir = new THREE.Vector3();
  camera.getWorldDirection(camDir);
  dragPlane.setFromNormalAndCoplanarPoint(camDir, worldPt);
  canvas.setPointerCapture(e.pointerId);
  e.stopPropagation();
}, true);

canvas.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  setDragPointer(e);
  dragRay.setFromCamera(dragPtr, camera);
  const worldPt = new THREE.Vector3();
  if (!dragRay.ray.intersectPlane(dragPlane, worldPt)) return;
  const local = content.worldToLocal(worldPt.clone());
  local.x = Math.max(-2.8, Math.min(2.8, local.x));
  local.y = Math.max(-2.8, Math.min(2.8, local.y));
  local.z = Math.max(-2.8, Math.min(2.8, local.z));
  if (dragging.which === 1) p1.copy(local); else p2.copy(local);
  updateFigure();
});

window.addEventListener('pointerup', () => {
  if (dragging) { dragging = null; controls.enabled = true; }
});

canvas.addEventListener('pointermove', (e) => {
  if (dragging) { canvas.style.cursor = 'grabbing'; return; }
  setDragPointer(e);
  dragRay.setFromCamera(dragPtr, camera);
  const hits = dragRay.intersectObjects([dot1, dot2], false);
  if (hits.length) canvas.style.cursor = 'grab';
});

registerInteractive(dot1, {
  title: 'Point P₁',
  tooltip: 'P₁ — drag to move',
  body: 'Position of the particle at time t₁. The vector r⃗(t₁) points from the origin here.'
});
registerInteractive(dot2, {
  title: 'Point P₂',
  tooltip: 'P₂ — drag to move',
  body: 'Position of the particle at time t₂. The displacement Δr⃗ = r⃗(t₂) − r⃗(t₁) always runs from P₁ to P₂.'
});

// ── Camera (after all geometry) ─────────────────────────────────────────────
// With the rotated content group, world +Y is the figure's z-axis (vertical),
// world +X is the figure's x-axis, and world -Z is the figure's y-axis.
// Azimuth 135° places the camera so +X projects to the lower-left and -Z to
// the right, matching the source tripod; world Y stays screen-vertical.
setCameraView({
  projection: 'orthographic',
  azimuthDeg: 135,
  elevationDeg: 18,
  rollDeg: 0,
  heightFraction: 0.65,
});

// Start fully built: r(t₁), r(t₂), and Δr all visible, closing the triangle.
goToStep(2);
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

